insert into public.project_showcases (id,sort_order,title,subtitle,category,location,carpet_area_sqft,duration_weeks,budget_paise,designer_name,hero_image,gallery_images,before_image,after_image,scope_highlights,materials_used,client_review) values
('proj_show_01',0,'The Glasshouse Residence','Modern Minimalist Villa with Courtyard Lightwells','Full Turnkey Villa','Indiranagar, Bengaluru',3450,16,485000000,'Rohan Varma (Lead Architect)','https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80',array['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=80','https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=1200&q=80']::text[],'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80',array['Custom rift-sawn European white oak wall panelling with concealed pivot doors','Recessed motorized acoustic blackout coves with smart architectural scenes','Monolithic Italian Calacatta Viola marble island and breakfast counter','Integrated Lutron architectural lighting with zero-glare recessed apertures']::text[],array['Rift-sawn White Oak','Calacatta Viola Marble','Brushed Unlacquered Brass','Acoustic Felt Baffles']::text[],'{"quote":"InterioFlow brought absolute structural transparency to what was previously a chaotic renovation. The contractor milestone progress tracking gave us total peace of mind.","author":"Sameer & Gayatri Nair","rating":5}'::jsonb),
('proj_show_02',1,'Komorebi Japandi Penthouse','Wabi-Sabi Aesthetics & Organic Natural Timber Millwork','Japandi Penthouse','Whitefield, Bengaluru',2800,14,360000000,'Rohan Varma (Lead Architect)','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1400&q=80',array['https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1400&q=80','https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1618219908412-a29a1bb7b86e?auto=format&fit=crop&w=1200&q=80']::text[],'https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=800&q=80',array['Hand-trowelled wabi-sabi lime plaster wall finishes throughout all living spaces','Concealed magnetic shoji pocket sliding partitions for flexible zoning','Low-profile elevated tatami lounge and tea room with concealed drawers','Custom unfilled Roman travertine coffee tables and dining surfaces']::text[],array['Natural Lime Plaster','Japanese Washi Paper','Romano Travertine','Belgian Flax Linen']::text[],'{"quote":"The combination of designer proposals in paise and real-time trade logs meant zero hidden expenses. The craftsmanship is world-class.","author":"Ananya Deshmukh","rating":5}'::jsonb),
('proj_show_03',2,'Heritage Teak Villa Restoration','Restoration & Modernization of 1950s Courtyard Residence','Heritage Renovation','Sadashivanagar, Bengaluru',4200,20,620000000,'Priya Sundaram (Senior Interior Architect)','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1400&q=80',array['https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1400&q=80','https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1600585152220-90363fe7e115?auto=format&fit=crop&w=1200&q=80']::text[],'https://images.unsplash.com/photo-1590381105924-c72589b9ef3f?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=800&q=80',array['Careful preservation of reclaimed 80-year Burmese teak structural ceiling beams','Athangudi handcrafted encaustic cement floor tiles paired with honed basalt','Central rainwater atrium with custom solar glass skylight and automated louvers','Seamless multi-zone VRV concealed air conditioning with architectural linear slots']::text[],array['Reclaimed Burmese Teak','Athangudi Handcrafted Tiles','Honed Basalt Stone','Antiqued Bronze']::text[],'{"quote":"They preserved the soul of our ancestral bungalow while elevating it into a 21st-century smart architectural residence.","author":"Dr. Vikramaditya Hegde","rating":5}'::jsonb),
('proj_show_04',3,'Biophilic Loft & Sky Garden','Sustainable Living Duplex with Double-Height Vertical Forest','Biophilic Loft','HSR Layout, Bengaluru',2400,12,310000000,'Rohan Varma (Lead Architect)','https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1400&q=80',array['https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1400&q=80','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1200&q=80','https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=1200&q=80']::text[],'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=800&q=80',array['Automated double-height living room flora wall with hydro-misting system','Zero-VOC mineral clay wall washes and non-toxic plant-oil hardwood sealants','Floor-to-ceiling thermally broken low-E argon double-glazed facade','Concealed solar battery integration for 100% resilient daytime operation']::text[],array['Thermally Modified Ash','Recycled Bio-Resin','Natural Raw Linen','Perforated Corten Steel']::text[],'{"quote":"Living in this duplex feels like breathing fresh mountain air in the middle of Bangalore. The biophilic design is extraordinary.","author":"Karan & Natasha Mehta","rating":5}'::jsonb);
